  const flying = { id: 10000, archetype: 'infected.runner', health: { current: 0, max: 100 }, combat: { radius: .3 },
    transform: { x: -20, y: .8, z: -20, yaw: 0 }, infected: { deadAt: 1 }, corpseThrown: true,
